#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"
CONFIG="$ROOT/artifacts/phase6/configs/gacr_v8_preregistered.json"
OUTPUT="$ROOT/artifacts/phase6/gacr_v8_validation_recovery"; LOG="$OUTPUT/run.log"; STATUS="$OUTPUT/status.json"; LEASE="$OUTPUT/gpu_lease.json"
SESSION=gram_phase6_gacr_v8; GPU=0; PYTHON=/home/jiangtangyunzhi/miniconda3/envs/gram-repro/bin/python3.9
WORKLOAD="$ROOT/experiment/phase6/gacr_v8.py"; TEST_FILE="$ROOT/experiment/phase6/test_gacr_v8.py"; PLAN="$ROOT/plan/第六阶段/GRAM_第六阶段_GACR-v8路径感知列表残差校准实验计划.md"
RESERVER="$ROOT/tools/run_codellama.sh"; RESERVER_SESSION=codellama; TELEMETRY_PID=""; LEASE_PID=""; WORKLOAD_PID=0; STARTED_AT=""; STAGE=not_started; RESERVATION=unchanged
export HF_HOME="$ROOT/.cache/huggingface" TRANSFORMERS_CACHE="$ROOT/.cache/huggingface"
reserver(){ env SESSION="$RESERVER_SESSION" HF_HOME=/home/jiangtangyunzhi/hf_cache HF_HUB_CACHE=/home/jiangtangyunzhi/hf_cache/hub TRANSFORMERS_CACHE=/home/jiangtangyunzhi/hf_cache/hub "$RESERVER" "$@"; }
write_status(){ mkdir -p "$OUTPUT"; printf '{"experiment_id":"GRAM_PHASE6_GACR_V8_PATH_AWARE_LISTWISE","status":"%s","stage":"%s","reason":"%s","started_at":"%s","updated_at":"%s","runner_pid":%s,"workload_pid":%s,"tmux_session":"%s","physical_gpu":0,"resource_reservation":"%s","test_read":false,"sports_read":false}\n' "$1" "$STAGE" "$2" "$STARTED_AT" "$(date -Is)" "$$" "$WORKLOAD_PID" "$SESSION" "$RESERVATION" > "$STATUS"; }
telemetry(){ printf 'timestamp,index,memory_used_mib,memory_free_mib,utilization_gpu_percent\n' > "$OUTPUT/gpu_telemetry.csv"; while true; do nvidia-smi --query-gpu=timestamp,index,memory.used,memory.free,utilization.gpu --format=csv,noheader,nounits --id=0 >> "$OUTPUT/gpu_telemetry.csv" || true; sleep 5; done; }
restore(){ STAGE=resource_restoration; RESERVATION=restoring_to_gpu0; write_status restoring_resource "Experiment ended; restoring CodeLlama."; reserver start 0 || true; for _ in $(seq 1 180); do value=$(reserver status 2>&1 || true); if [[ "$value" == *"tmux session: running (codellama)"* && "$value" == *"state=running"* ]]; then RESERVATION=restored_on_gpu0; return 0; fi; sleep 5; done; RESERVATION=restore_failed_on_gpu0; return 1; }
finish(){ rc=$?; trap - EXIT INT TERM HUP; [[ -n "$TELEMETRY_PID" ]] && kill "$TELEMETRY_PID" 2>/dev/null || true; [[ -n "$LEASE_PID" ]] && kill "$LEASE_PID" 2>/dev/null || true; restore || true; STAGE=finished; result=""; [[ -s "$OUTPUT/summary.json" ]] && result=$("$PYTHON" -c 'import json,sys; print(json.load(open(sys.argv[1])).get("result_status", ""))' "$OUTPUT/summary.json" 2>/dev/null || true); if ((rc==0)) && [[ "$result" == STOPPED_BEFORE_FRESH_VALIDATION_CALIBRATION_GATE_FAILED ]]; then write_status completed_without_validation "D/E calibration gate failed; fresh validation was not read."; elif ((rc==0)); then write_status succeeded "GACR-v8 completed; results await researcher analysis."; else write_status failed "Experiment exit=$rc; no automatic retry."; fi; exit "$rc"; }
verify(){ "$PYTHON" - "$CONFIG" "$WORKLOAD" "$TEST_FILE" "$0" "$PLAN" <<'PY'
import hashlib,json,pathlib,sys
c=json.loads(pathlib.Path(sys.argv[1]).read_text())
if c.get('decision_status_before_run') != 'PREREGISTERED_FROZEN_READY_TO_RUN': raise SystemExit('v8 config is not execution-enabled')
for key,path in zip(('implementation_sha256','test_sha256','runner_sha256','plan_sha256'),map(pathlib.Path,sys.argv[2:])):
    if hashlib.sha256(path.read_bytes()).hexdigest()!=c['implementation_lock'][key]: raise SystemExit(f'frozen material mismatch: {path}')
PY
}
worker(){ STARTED_AT=$1; trap finish EXIT; cd "$ROOT"; STAGE=preflight; write_status preflight "Checking frozen v8 validation-recovery materials."; for f in "$CONFIG" "$WORKLOAD" "$TEST_FILE" "$PLAN" "$ROOT/artifacts/phase6/gacr_v8_recovery/summary.json" "$ROOT/artifacts/phase4/gcdh_p0/Toys/C1/model.pt" "$ROOT/artifacts/phase4/gcdh_p0/Beauty/C1/model.pt"; do [[ -s "$f" ]] || { write_status blocked "Required material missing: $f"; exit 2; }; done; verify; "$PYTHON" -m pytest -q "$TEST_FILE"; STAGE=resource_release; write_status releasing_resource "Stopping CodeLlama before v8 validation recovery."; reserver stop; RESERVATION=released_for_experiment; STAGE=gpu_memory_gate; write_status waiting_for_gpu "Waiting for 30720 MiB free on GPU0."; free=""; for _ in $(seq 1 720); do free=$(nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits --id=0 2>/dev/null|tr -d ' '||true); [[ "$free" =~ ^[0-9]+$ ]] && ((free>=30720)) && break; sleep 60; done; [[ "$free" =~ ^[0-9]+$ ]] && ((free>=30720)) || { write_status blocked "GPU0 admission failed: ${free:-unknown} MiB free."; exit 3; }; STAGE=memory_lease; "$PYTHON" "$ROOT/experiment/gpu_memory_lease.py" --gpu 0 --total-lease-mib 30720 --expected-workload-peak-mib 24576 --status-path "$LEASE" & LEASE_PID=$!; sleep 5; grep -q '"state": "holding"' "$LEASE" || { write_status blocked "GPU lease sidecar did not hold."; exit 4; }; telemetry & TELEMETRY_PID=$!; STAGE=gacr_v8_validation_only; timeout --signal=TERM 172800 env CUDA_VISIBLE_DEVICES=0 "$PYTHON" "$WORKLOAD" --config "$CONFIG" --output-root "$OUTPUT" --validation-only --checkpoint-root "$ROOT/artifacts/phase6/gacr_v8_recovery" & WORKLOAD_PID=$!; write_status running "GACR-v8 E-only fresh validation recovery running."; wait "$WORKLOAD_PID"; }
case "${1:-status}" in
 start) mkdir -p "$OUTPUT"; tmux has-session -t "$SESSION" 2>/dev/null && { echo "session already exists" >&2; exit 1; }; STARTED_AT=$(date -Is); printf -v cmd 'bash %q worker %q >> %q 2>&1' "$0" "$STARTED_AT" "$LOG"; tmux new-session -d -s "$SESSION" "$cmd"; STAGE=starting; RESERVATION=scheduled_for_release; write_status starting "Persistent v8 session started."; echo "started $SESSION";;
 worker) worker "${2:?missing start timestamp}";;
 status) tmux has-session -t "$SESSION" 2>/dev/null && echo "tmux session: running ($SESSION)" || echo "tmux session: not running ($SESSION)"; [[ -f "$STATUS" ]] && sed -n '1,100p' "$STATUS" || echo '{"status":"not_started"}'; [[ -f "$LOG" ]] && tail -n 40 "$LOG";;
 *) echo "usage: $0 {start|status|worker}" >&2; exit 2;; esac
